from decimal import Decimal, ROUND_HALF_UP
import datetime

def fifo_report(trades: list[dict]) -> dict:
    if not isinstance(trades, list):
        raise ValueError("trades must be a list")
    Q2 = Decimal("0.00")
    Q4 = Decimal("0.0000")
    lots = []
    sales = []
    for trade in trades:
        if not isinstance(trade, dict):
            raise ValueError("trade must be dict")
        if "date" not in trade or "side" not in trade or "quantity" not in trade or "price" not in trade:
            raise ValueError("missing required key")
        date_s = trade["date"]
        side = trade["side"]
        qty = trade["quantity"]
        price_s = trade["price"]
        if not isinstance(date_s, str):
            raise ValueError("bad date")
        if len(date_s) != 10 or date_s[4] != "-" or date_s[7] != "-":
            raise ValueError("bad date")
        ys = date_s[0:4]
        ms = date_s[5:7]
        ds = date_s[8:10]
        def _all_ascii_digits(s):
            if len(s) == 0:
                return False
            for ch in s:
                if not ("0" <= ch <= "9"):
                    return False
            return True
        if not (_all_ascii_digits(ys) and _all_ascii_digits(ms) and _all_ascii_digits(ds)):
            raise ValueError("bad date")
        try:
            datetime.date(int(ys), int(ms), int(ds))
        except Exception:
            raise ValueError("bad date")
        if side not in ("BUY", "SELL"):
            raise ValueError("bad side")
        if isinstance(qty, bool) or not isinstance(qty, int):
            raise ValueError("bad quantity")
        if qty <= 0:
            raise ValueError("bad quantity")
        if not isinstance(price_s, str):
            raise ValueError("bad price")
        try:
            price_d = Decimal(price_s)
        except Exception:
            raise ValueError("bad price")
        if not price_d.is_finite():
            raise ValueError("bad price")
        if price_d <= 0:
            raise ValueError("bad price")
        if price_d.as_tuple().exponent < -4:
            raise ValueError("bad price")
        if "fee" in trade:
            fee_s = trade["fee"]
            if not isinstance(fee_s, str):
                raise ValueError("bad fee")
            try:
                fee_d = Decimal(fee_s)
            except Exception:
                raise ValueError("bad fee")
            if not fee_d.is_finite():
                raise ValueError("bad fee")
            if fee_d < 0:
                raise ValueError("bad fee")
            if fee_d.as_tuple().exponent < -2:
                raise ValueError("bad fee")
        else:
            fee_d = Decimal("0.00")
        if side == "BUY":
            total_cost = Decimal(qty) * price_d + fee_d
            lots.append([qty, total_cost])
        else:
            inv = 0
            for lq, _lc in lots:
                inv += lq
            if inv < qty:
                raise ValueError("insufficient inventory")
            proceeds_exact = Decimal(qty) * price_d - fee_d
            cost_consumed = Decimal(0)
            need = qty
            while need > 0:
                lq, lc = lots[0]
                if lq <= need:
                    cost_consumed += lc
                    need -= lq
                    lots.pop(0)
                else:
                    taken = need
                    consumed = lc * Decimal(taken) / Decimal(lq)
                    cost_consumed += consumed
                    new_lq = lq - taken
                    new_lc = lc - consumed
                    lots[0] = [new_lq, new_lc]
                    need = 0
            realized_exact = proceeds_exact - cost_consumed
            proceeds_q = proceeds_exact.quantize(Q2, rounding=ROUND_HALF_UP)
            cost_q = cost_consumed.quantize(Q2, rounding=ROUND_HALF_UP)
            realized_q = realized_exact.quantize(Q2, rounding=ROUND_HALF_UP)
            sales.append({"date": date_s, "quantity": qty, "proceeds": proceeds_q, "cost": cost_q, "realized": realized_q})
    if len(sales) == 0:
        total_realized = Decimal("0.00")
    else:
        s = Decimal("0.00")
        for e in sales:
            s += e["realized"]
        total_realized = s.quantize(Q2, rounding=ROUND_HALF_UP)
    remaining = []
    inv_qty = 0
    for lq, lc in lots:
        if lq > 0:
            total_q = lc.quantize(Q2, rounding=ROUND_HALF_UP)
            unit_q = (lc / Decimal(lq)).quantize(Q4, rounding=ROUND_HALF_UP)
            remaining.append({"quantity": lq, "unit_cost": unit_q, "total_cost": total_q})
            inv_qty += lq
    return {"sales": sales, "total_realized": total_realized, "remaining": remaining, "inventory_quantity": inv_qty}
